\label{defi:pH}
A {\bf post-Hopf algebra} is a pair $(H,\rhd)$, where $H$ is a Hopf algebra and $\rhd:H\otimes H\to H$ is a coalgebra homomorphism satisfying the following equalities:
\begin{eqnarray}
\label{Post-2}x\rhd (y\cdot z)&=&(x_1\rhd y)\cdot(x_2\rhd z),\\
\label{Post-4}x\rhd (y\rhd z)&=&\big(x_1\cdot(x_2\rhd y)\big)\rhd z,
\end{eqnarray}
for any $x,y,z\in H$, and the left multiplication $\alpha_\rhd:H\to \End(H)$ defined by
$$\alpha_{\rhd, x} y= x\rhd y,\quad\forall x,y\in H,$$
is convolution invertible in $\Hom(H,\End(H))$. Namely, there exists a unique linear map $\beta_\rhd:H\to\End(H)$ such that
\begin{equation}\label{Post-con}
\alpha_{\rhd,x_1}\beta_{\rhd,x_2}=\beta_{\rhd,x_1}\alpha_{\rhd,x_2}=\vep(x)\id_H,\quad\forall x\in H.
\end{equation}

Let $(H,\rhd)$ be a post-Hopf algebra. Then for all $x,y\in H$, we have
\begin{eqnarray}
\label{Post-1}x\rhd 1&=&\vep(x)1,\\
\label{Post-3}1\rhd x&=&x,\\
\label{Post-5}S(x\rhd y)&=&x\rhd S(y).
\end{eqnarray}

\label{thm:subHopf}
Let $(H,\rhd)$ be a cocommutative post-Hopf algebra. Then
$$H_\rhd\coloneqq(H,\circ ,1,\Delta,\vep,S_\rhd)$$
is a Hopf algebra, which is called the {\bf sub-adjacent Hopf algebra}, where for all $x,y\in H$,
\begin{eqnarray}
\label{post-rbb-1}x \circ  y&\coloneqq&x_1\cdot (x_2\rhd y),\\
\label{post-rbb-2}S_\rhd(x)&\coloneqq&\beta_{\rhd,x_1}(S(x_2)).
\end{eqnarray}

Furthermore, $H$ is a left $H_\rhd$-module bialgebra via the action $\rhd$.

(i) The product \eqref{post-rbb-1} generalizes the Grossman-Larson product \cite{GL,MW,OG} defined in the context of (noncommutative) polynomials of ordered trees and widely applied to the study of Magnus expansions \cite{EMQ} and Lie-Butcher series \cite{ML,MW}. A proper generalization of the Grossman-Larson product to the universal enveloping algebra of a post-Lie algebra was already presented in \cite{ELM}.

(ii) Since $\beta_\rhd$ is the convolution inverse of $\alpha_\rhd$ and
$$\alpha_{\rhd,x_1}\alpha_{\rhd,S_\rhd(x_2)}\stackrel{\eqref{Post-4},\,\eqref{post-rbb-1}}{=}
\alpha_{\rhd,x_1\circ  S_\rhd(x_2)}=\alpha_{\rhd,\vep(x)1}\stackrel{\eqref{Post-3}}{=}\vep(x)\id,$$
we have $\beta_{\rhd,x}=\alpha_{\rhd,S_\rhd(x)}$. Namely, Eq.~\eqref{post-rbb-2} is rewritten as
\begin{equation}\label{post-rbb-2'}
S_\rhd(x)=S_\rhd(x_1)\rhd S(x_2),\quad\forall x\in H.
\end{equation}

\label{th:post-uea}
Let $(\frakg,[\cdot,\cdot]_\frakg,\rhd)$ be a post-Lie algebra associated with the sub-adjacent Lie algebra $\frakg_\rhd$. Then  $(\U(\frakg), \rhd)$ is a post-Hopf algebra with the product $\rhd$ recursively defined by
\begin{align*}
&x\rhd 1=0,\quad x\rhd x_1\cdots x_r=\sum_{i=1}^r x_1\cdots (x\rhd x_i)\cdots x_r,\\
&1\rhd u = u,\quad x_1\cdots x_r\rhd u = x_1\rhd(x_2\cdots x_r\rhd u)-(x_1\rhd x_2\cdots x_r)\rhd u
\end{align*}
for all $x,x_1,\dots,x_r\in \frakg$ and $u\in \U(\frakg)$ with $r\geq1$.

Moreover, there is a Hopf algebra isomorphism $\phi:\U(\frakg_\rhd)\to \U(\frakg)_\rhd$ defined by $$\phi(x_1\cdots x_r)=x_1\circ \cdots\circ  x_r,\quad \forall x_1,\dots,x_r\in \frakg.$$
We call $\phi$ {\bf the Guin-Oudom isomorphism}.

For any word $X\in \mathsf{T}(V)$ with at most $m$ letters in $V$ $(m\geq1)$,
\begin{equation}\label{post-rbb-2''}
S_\rhd(X)=(\cdots(S(X_1)\rhd S(X_2))\rhd \cdots )\rhd S(X_m).
\end{equation}

Define a binary product $\btr$ on $\mathsf{T}(V)$ as follows,
\begin{equation}\label{eq:btr}
X \btr Y\coloneqq (-1)^{|X|}\beta_{\rhd,X}Y=(-1)^{|X|}S_\rhd(X)\rhd Y
\end{equation}
for any words $X,\,Y\in \mathsf{T}(V)$, with $|X|$ as the number of letters in $X$, i.e. its natural degree in $\mathsf{T}(V)$.

\label{prop:antipode}
The following formula holds for the antipode $S_\rhd$ of $\mathsf{T}(V)_\rhd$,
\begin{equation}\label{eq:antipode}
S_\rhd(x_1\cdots x_m)=(-1)^m\sum_\pi (x_{B_1}\btr x_{b_1})\cdots(x_{B_{|\pi|-1}}\btr x_{b_{|\pi|-1}}),\quad \forall x_1,\dots, x_m\in V,
\end{equation}
where the sum ranges over all partitions $\pi$ of $[m]$ into a tuple $(B_1,\dots,B_{|\pi|})$ of possibly empty subsets such that
$B_{|\pi|}=\{b_1>\cdots>b_{|\pi|-1}\}$.

For any word $Y$ in $\mathsf{T}(V)$, let $Y^{\rm op}$ be its reverse. By formula~\eqref{eq:cosh_coproduct} of the iterated coshuffle coproduct, we have
\begin{eqnarray*}
S_\rhd(x_1\cdots x_m)&\stackrel{\eqref{post-rbb-2'}}{=}&
\sum_{\pi:|\pi|=2} S_\rhd(x_{B_1})\rhd S(x_{B_2})\\
&\stackrel{\eqref{Post-1},\,\eqref{eq:antipo}}{=}&
\sum_{\pi:|\pi|=2,\,B_2\neq\emptyset}(-1)^{|B_2|}
S_\rhd(x_{B_1})\rhd x_{B_2}^{\rm op}\\
&\stackrel{\eqref{eq:btr}}{=}&(-1)^m\sum_{\pi:|\pi|=2,\,B_2\neq\emptyset}
x_{B_1}\btr x_{B_2}^{\rm op}\\
&\stackrel{\eqref{eq:btr_coalg}}{=}&(-1)^m\sum_\pi (x_{B_1}\btr x_{b_1})\cdots(x_{B_{|\pi|-1}}\btr x_{b_{|\pi|-1}}),
\end{eqnarray*}
where the sum in the last equality ranges over all partitions $\pi$ of $[m]$ under the stated condition. Note that each term $(x_{B_1}\btr x_{b_1})\cdots(x_{B_{|\pi|-1}}\btr x_{b_{|\pi|-1}})$ is a homogeneous polynomial in $\mathsf{T}(V)$ of degree $|\pi|-1$.

\label{lem:btr_recursive}
For any letters $x_1,\dots,x_m\in V$ with $m\geq2$ and word $Y\in\mathsf{T}(V)$, the following recursive formula holds,
\begin{equation}\label{eq:btr_recursive}
x_1\cdots x_m \btr Y = x_2 \cdots x_m \btr (x_1 \rhd Y) + \sum_{i=2}^m x_2\cdots(x_1\rhd x_i)\cdots x_m \btr Y.
\end{equation}

\label{defn:nest}
For any letters $x_1,\dots,x_m\in V$, word $Y\in\mathsf{T}(V)$ and permutation $w\in S_m$ (with one-word notation), we define a specific element
$$[x_1,\dots,x_m;Y]_w$$
in $\mathsf{T}(V)$ by the following steps,
\begin{enumerate}[(i)]
\item\label{step1}
 Begin with the sequence $x_{w(1)}\ \cdots\ x_{w(m)}\ Y$.
 First use a pair of parentheses to enclose $x_1$ and its right adjacent letter $x_{w(w^{-1}(1)+1)}$ or right adjacent word $Y$, then use the product $\rhd$ to merge them.

\item\label{step2}
Next enclose the letter involving $x_2$ and its right adjacent letter, or right adjacent word involving $Y$ by a pair of parentheses, and then use the product $\rhd$ to merge them.

\item\label{step3}
Iteratively carry on such a procedure for letters involving $x_3,\dots, x_m$ successively, until there have been $m-1$ pairs of parentheses and $m$ symbols $\rhd$ inserted. The resulting element in $\mathsf{T}(V)$ is $[x_1,\dots,x_m;Y]_w$.
\end{enumerate}

\label{prop:btr}
For any letters $x_1,\dots,x_m\in V$ and word $Y\in \mathsf{T}(V)$,
\begin{equation}\label{eq:btr_comb}
x_1\cdots x_m \btr Y = \sum_{w\in S_m}[x_1,\dots,x_m;Y]_w.
\end{equation}

\label{thm:antipode_uea}
Given a post-Lie algebra $(\frakg,[\cdot,\cdot]_\frakg,\rhd)$, the antipode $S_\rhd$ of the sub-adjacent Hopf algebra $\U(\frakg)_\rhd$ is given by
\begin{equation}\label{eq:antipode_uea}
S_\rhd(x_1\cdots x_m)=(-1)^m\sum_\pi [x_{B_1}; x_{b_1}]\cdots[x_{B_{|\pi|-1}}; x_{b_{|\pi|-1}}],\quad \forall x_1,\dots, x_m\in \frakg,
\end{equation}
where the sum ranges over all partitions $\pi$ of $[m]$ into a tuple $(B_1,\dots,B_{|\pi|})$ of possibly empty subsets such that
$B_{|\pi|}=\{b_1>\cdots>b_{|\pi|-1}\}$. Also, we use the same abbreviation  $[x_I;y]\coloneqq\sum_{w\in S_r}[x_{i_1},\dots, x_{i_r};y]_w\in \frakg$ as in
the proof of Proposition~\ref{prop:btr} for any $I=\{i_1<\cdots< i_r\}\subseteq[m]$ and $y\in\frakg$. In particular, $[x_\emptyset;y]=y$.

For the post-Hopf algebra $(\mathsf{T}(V),\cdot\,,\Delta_\shuffle,\rhd)$ given in Proposition~\ref{magma-to-post},
there exists a Hopf algebra isomorphism $K:\mathsf{T}(V)_\rhd\to \mathsf{T}(V)$ called {\bf the $K$-map} and recursively defined by
\begin{equation}\label{eq:K-map}
K(x)=x\quad \mbox{and}\quad K(x_1\cdots x_n)=x_1K(x_2\cdots x_n) - \sum_{i=2}^n K(x_2\cdots x_{i-1}(x_1\rhd x_i)x_{i+1}\cdots x_n)
\end{equation}
for any $x,x_1,\dots,x_n\in V$.

\label{prop:K-map'}
The $K$-map $K:\mathsf{T}(V)_\rhd\to \mathsf{T}(V)$ is given by
\begin{equation}\label{eq:K-map'}
K(x_1\cdots x_n)=\sum_\pi(-1)^{n-|\pi|} x^\btr_{B_1}\cdots x^\btr_{B_{|\pi|}},\quad
\forall x_1,\dots,x_n\in V,
\end{equation}
where the sum ranges over all set partitions  $\pi=(B_1,\dots,B_{|\pi|})$ of $[n]$ with blocks $B_1,\dots,B_{|\pi|}$ satisfying $\max B_1<\cdots<\max B_{|\pi|}$, and
$$x^\btr_I\coloneqq x_{i_1}\cdots x_{i_{r-1}}\btr x_{i_r}\stackrel{\eqref{eq:btr_comb}}{=}\sum_{w\in S_{r-1}}[x_{i_1},\dots, x_{i_{r-1}};x_{i_r}]_w\in V$$
for any $I=\{i_1<\cdots< i_r\}\subseteq[n]$, with the convention that $x^\btr_{\{i\}}=x_i$, $\forall i\in [n]$.

\label{prop:K-map-OG}
For a post-Lie algebra $(\frakg,[\cdot,\cdot]_\frakg,\rhd)$,
the inverse $K^{-1}:\mathsf{T}(\frakg)\to\mathsf{T}(\frakg)_\rhd$ induces the Guin-Oudom isomorphism $\phi:\U(\frakg_\rhd)\to \U(\frakg)_\rhd$,

\label{thm:hopf-iso-inv}
The inverse $\phi^{-1}:\U(\frakg)_\rhd\to \U(\frakg_\rhd)$ of the Guin-Oudom isomorphism is given by
\begin{equation}\label{eq:hopf-iso-inv}
\phi^{-1}(x_1\cdots x_n)=\sum_\pi(-1)^{n-|\pi|} [x_{B_1}]\cdots [x_{B_{|\pi|}}],\quad
\forall x_1,\dots,x_n\in \frakg,
\end{equation}
where the sum ranges over all set partitions  $\pi=(B_1,\dots,B_{|\pi|})$ of $[n]$ with blocks $B_1,\dots,B_{|\pi|}$ satisfying $\max B_1<\cdots<\max B_{|\pi|}$, and
$[x_I]\coloneqq\sum_{w\in S_{r-1}}[x_{i_1},\dots, x_{i_{r-1}};x_{i_r}]_w\in \frakg$ for any $I=\{i_1<\cdots< i_r\}\subseteq[n]$, with the convention that $[x_{\{i\}}]=x_i$, $\forall i\in [n]$.

\label{prop:rRB}
The inverse $\phi^{-1}:\U(\frakg)\to\U(\frakg_\rhd)$ is a relative Rota-Baxter operator with respect to $\rightharpoonup$ in the sense of \cite[Def.~3.1]{LST}. Namely, $\phi^{-1}$ is a coalgebra homomorphism satisfying
$$\phi^{-1}(X)\phi^{-1}(Y)=\phi^{-1}(X_1(\phi^{-1}(X_2)\rightharpoonup Y)),\quad \forall X,Y\in \U(\frakg).$$

\label{thm:ta}
Any graded, connected ${\mathbf{k}}$-bialgebra $(B,m,u,\Delta,\vep)$ is a Hopf algebra with its antipode $S$ given by
\begin{equation}\label{eq:ta}
S =\sum_{i\ge 0} (-1)^i p^{\star i}=\sum_{i\ge 0} (-1)^i m^{(i-1)} p^{\otimes i} \Delta^{(i-1)},
\end{equation}
where $\star$ is the convolution product, $u$ is the unit map, $p\coloneqq\id-u\vep$, $m^{(-1)} \coloneqq u$, and $\Delta^{(-1)} \coloneqq \vep$.

\label{prop:GL_iso}
The sub-adjacent Hopf algebra ${\mathbf{k}}\{{\mathcal{OF}}\}_\rhd=({\mathbf{k}}\{{\mathcal{OF}}\},{\circ },\Delta_\shuffle,S_\rhd)$ is isomorphic to the Grossman-Larson Hopf algebra $\mathcal{H}_{GL}$ of ordered trees via the root grafting operator $B^+$. Also, using the post-Hopf product $\rhd$, the multiplication $\circ $ can be given by
\begin{eqnarray*}
\mathcal{X} \circ  \mathcal{Y}&=&B^-(\mathcal{X}\rhd B^+(\mathcal{Y})),\quad \forall \mathcal{X},\mathcal{Y}\in{\mathcal{OF}}.
\end{eqnarray*}
Equivalently,
$$\tau \circ_{GL} \omega = B^-(\tau)\rhd \omega,\quad \forall \tau,\omega\in{\mathcal{OT}}.$$

